import{_ as o}from"./chunks/analytics_apple.i3PNHCzB.js";import{_ as t}from"./chunks/analytics_hosting.D4xMhqgc.js";import{_ as s}from"./chunks/analytics_hopr.CdeS75_P.js";import{_ as n,c as a,b as r,a2 as i}from"./chunks/framework.BEqfOpL-.js";const h="/images/analytics_spotify_setup.webp",k=JSON.parse('{"title":"Connect Your Analytics","description":"Your listening numbers are scattered: Spotify for Creators has one set, Apple Podcasts Connect another, YouTube Studio a third, and your podcast host yet another. Analytics connections bring them into PodSEO, so you can see plays, listeners, followers and downloads on the same screen as your keyword rankings and visibility, and judge whether your SEO work is turning into an audience.","frontmatter":{},"headers":[],"relativePath":"features/analytics-connections.md","filePath":"features/analytics-connections.md"}'),l={name:"features/analytics-connections.md"};function d(c,e,p,u,g,y){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="connect-your-analytics" tabindex="-1">Connect Your Analytics <a class="header-anchor" href="#connect-your-analytics" aria-label="Permalink to &quot;Connect Your Analytics&quot;">​</a></h1><h2 id="all-your-numbers-in-one-place-next-to-your-rankings" tabindex="-1">All Your Numbers in One Place, Next to Your Rankings <a class="header-anchor" href="#all-your-numbers-in-one-place-next-to-your-rankings" aria-label="Permalink to &quot;All Your Numbers in One Place, Next to Your Rankings&quot;">​</a></h2><p>Your listening numbers are scattered: Spotify for Creators has one set, Apple Podcasts Connect another, YouTube Studio a third, and your podcast host yet another. Analytics connections bring them into PodSEO, so you can see plays, listeners, followers and downloads on the same screen as your keyword rankings and visibility, and judge whether your SEO work is turning into an audience.</p><p>Every connection is <strong>free on every plan</strong>, including the Free plan. You can connect as many sources as apply to your show; use the source bar to switch between the reports available for your show.</p><p><strong>To access</strong>: Click <strong>Measure → Analytics</strong> in the sidebar. Select <strong>Spotify</strong>, <strong>YouTube</strong>, <strong>Apple Podcasts</strong>, your host (<strong>Spreaker</strong>, <strong>Buzzsprout</strong>, <strong>Simplecast</strong>, <strong>Captivate</strong>, <strong>Transistor</strong> or <strong>Podigee</strong>), <strong>Tracker</strong> (OP3), or <strong>hopr.fm</strong>, as applicable. The <strong>Overview</strong> source tab compares your connected reports; see <a href="/features/analytics.html">Reading Analytics</a>.</p><p><strong>To manage existing access</strong>: Open <strong>Settings → Connections</strong>, filter by podcast, and expand the provider. You can also follow <strong>Manage connections</strong> links from the product.</p><p><a href="/images/analytics_spotify_setup.webp" title="Open screenshot at full size"><img src="'+h+'" alt="Start a Spotify analytics connection"></a></p><p><strong>Who can connect</strong>: In a personal account, you can connect and disconnect everything. In an organization, only <strong>Admins</strong> and <strong>Owners</strong> can connect or disconnect a source; other team members can view the numbers.</p><p><strong>Read-only analytics</strong>: Analytics reads reports rather than changing your podcast or videos. Use the connection method shown for each source. Buzzsprout and Simplecast use an account API token (Simplecast&#39;s is read-only); the other supported private sources use invitations or their own sign-in screens.</p><hr><p>For the connected screens, see the dedicated report guides: <a href="/features/spotify-analytics.html">Spotify</a>, <a href="/features/apple-podcasts-analytics.html">Apple Podcasts</a>, <a href="/features/hosting-analytics.html">Hosting</a>, <a href="/features/op3-analytics.html">OP3</a> and <a href="/features/hopr-fm-analytics.html">hopr.fm</a>. This page focuses on establishing and managing access.</p><h2 id="what-happens-after-i-connect" tabindex="-1">What happens after I connect? <a class="header-anchor" href="#what-happens-after-i-connect" aria-label="Permalink to &quot;What happens after I connect?&quot;">​</a></h2><p>A connection being accepted and its reports being ready are separate steps. Read the status message: it tells you whether PodSEO is waiting for the invitation, needs your confirmation, or is importing reports. <strong>Connected</strong> does not mean the provider has released figures for today&#39;s episode.</p><table tabindex="0"><thead><tr><th>Source</th><th>What you do</th><th>What to expect next</th><th>If you are stuck</th></tr></thead><tbody><tr><td>Spotify</td><td>Invite the PodSEO address with your code and Analytics → Reader, then click <strong>I&#39;ve sent the invite</strong></td><td>Invitations are checked every 10 minutes. Once connected, the first plays appear within a day; plays then refresh daily. Other reports have their own dates.</td><td>Open <strong>Problems connecting?</strong> if the show is missing. If PodSEO is already a team member, fix its access rather than inviting it again.</td></tr><tr><td>Apple Podcasts</td><td>Invite PodSEO as Analyst for the correct show</td><td>Invitations are checked every 10 minutes. Verification may be automatic or require the RSS owner&#39;s approval. Reports are read daily after connection.</td><td>Follow the status card for owner-email or confirmation issues; use <strong>Problems connecting?</strong> if the show is absent from your Apple account.</td></tr><tr><td>YouTube</td><td>Authorize the correct channel with Google</td><td>The first connection starts Insights automatically. The six-month import usually takes a few minutes. Core figures refresh daily; breakdowns weekly.</td><td>Check the channel&#39;s name and Google/Brand Account. If <strong>Activate Insights</strong> is shown, select it.</td></tr><tr><td>Spreaker / Buzzsprout / Simplecast / Captivate / Transistor / Podigee</td><td>Authorize Spreaker, paste your Buzzsprout or Simplecast token, paste your Captivate User ID and API Key, paste your Transistor API key, or paste a Podigee MCP token</td><td>The first import starts after the feed is matched. Downloads refresh daily; older history may still be importing.</td><td>Confirm that the account hosts this feed. Spreaker and Buzzsprout feeds on custom domains or proxies cannot be matched automatically yet.</td></tr><tr><td>Megaphone</td><td>Invite <a href="mailto:megaphone@podseo.com" target="_blank" rel="noreferrer">megaphone@podseo.com</a> as Network Partner, with your PodSEO code as the Last name</td><td>Invitations are checked every 10 minutes. Downloads appear after the first import, then refresh daily.</td><td>Only an Organization Admin or Network Admin can invite. If the code expired (30 days), get a new one. Step-by-step: <a href="/features/megaphone-connection.html">Megaphone guide</a>.</td></tr><tr><td>OP3</td><td>Add the OP3 prefix in your host, if you use OP3</td><td>PodSEO discovers the prefix when it next checks your feed, which can take up to a week. Reports appear after downloads have been counted.</td><td>Confirm the prefix is in the feed; adding it does not create historical downloads.</td></tr><tr><td>hopr.fm</td><td>Get your prefix, add it in your host and re-check the feed</td><td>New downloads passing through the prefix are processed throughout the day.</td><td>Confirm the prefix is present in the feed and audio URLs. It cannot count downloads from before installation.</td></tr></tbody></table><p>Apple and Spotify may not have released reports for your newest episodes yet. Check the dates on each report before reconnecting. If the status asks you to wait, you can leave the page; PodSEO emails you when Apple or Spotify connects if your notification settings allow it.</p><h2 id="why-are-my-downloads-missing" tabindex="-1">Why are my downloads missing? <a class="header-anchor" href="#why-are-my-downloads-missing" aria-label="Permalink to &quot;Why are my downloads missing?&quot;">​</a></h2><p>First check that you selected the right show and source in <strong>Analytics</strong>, and read the connection status and report dates. A newly connected host may still be importing; host downloads refresh daily after the feed is matched. If the host tab is missing, confirm that the connected account hosts this feed. Some custom or proxied Spreaker and Buzzsprout feeds cannot be matched automatically yet.</p><p>If you use <strong>OP3</strong> or <strong>hopr.fm</strong>, make sure its prefix appears in your feed and audio URLs. Prefixes count downloads after they are installed; they cannot supply downloads from before installation. OP3 discovery can take up to a week. See <a href="/features/hosting-analytics.html">Hosting reports</a>, <a href="/features/op3-analytics.html">OP3 reports</a>, or <a href="/features/hopr-fm-analytics.html">hopr.fm reports</a> for the source you use. If the status still needs attention, <a href="https://podseo.com/contact/" target="_blank" rel="noreferrer">contact support</a> with the show and source; do not send your API token.</p><h2 id="spotify-for-creators" tabindex="-1"><strong>Spotify for Creators</strong> <a class="header-anchor" href="#spotify-for-creators" aria-label="Permalink to &quot;**Spotify for Creators**&quot;">​</a></h2><p>Spotify&#39;s own data on how listeners discover and play your show: where impressions come from, how many turn into plays, and who your listeners are.</p><h3 id="how-to-connect" tabindex="-1"><strong>How to connect</strong> <a class="header-anchor" href="#how-to-connect" aria-label="Permalink to &quot;**How to connect**&quot;">​</a></h3><p>Your show needs to be linked to Spotify in PodSEO first (you can check this on the <a href="/features/distribution-health.html">Distribution Health</a> page).</p><ol><li>Open <strong>Analytics</strong> and select the <strong>Spotify</strong> tab. Click <strong>Connect Spotify</strong> to get your show&#39;s code. The code is valid for 30 days.</li><li>In <strong>Spotify Manage</strong>, open <strong>Teams</strong>, choose the <strong>podcast&#39;s team</strong>, and invite <code>spotify@podseo.com</code>.</li><li>Paste the PodSEO code into the invite&#39;s <strong>Title</strong> field. This is how PodSEO knows the invite comes from you. Leave <strong>Set team member as team admin</strong> off, then click <strong>Next</strong>.</li><li>Set <strong>Analytics</strong> to <strong>Reader</strong> and leave everything else (Episodes, Interact, Monetize, Settings) on <strong>No access</strong>.</li><li>Send the invite, then return to PodSEO and click <strong>I&#39;ve sent the invite</strong>. Follow the status card while PodSEO confirms access and imports your reports.</li></ol><p>If PodSEO is already on your Spotify team but cannot read analytics, edit that member&#39;s permissions in Spotify Manage: set <strong>Analytics → Reader</strong>. You do not need to send another invite. Return to PodSEO and use <strong>Check access now</strong> when offered. If PodSEO was removed from the team, follow <strong>Connect again</strong> to send a new invitation.</p><p>Someone else manages the show&#39;s team on Spotify (a producer, network or agency)? Forward them the steps and your code: the connection still comes to your PodSEO account.</p><h3 id="how-long-does-the-spotify-connection-take" tabindex="-1">How long does the Spotify connection take? <a class="header-anchor" href="#how-long-does-the-spotify-connection-take" aria-label="Permalink to &quot;How long does the Spotify connection take?&quot;">​</a></h3><p>After you send the invitation and click <strong>I&#39;ve sent the invite</strong>, PodSEO checks for it every 10 minutes. Once connected, the first plays normally appear within a day and then refresh daily. Other reports have their own dates. Read the status card for the next step if the connection is still pending.</p><h3 id="why-is-spotify-not-syncing" tabindex="-1">Why is Spotify not syncing? <a class="header-anchor" href="#why-is-spotify-not-syncing" aria-label="Permalink to &quot;Why is Spotify not syncing?&quot;">​</a></h3><p>If there are no Spotify plays or analytics are not updating, open <strong>Analytics → Spotify</strong> and check the selected show, connection status, and report dates. See <a href="#how-long-does-the-spotify-connection-take">how long the Spotify connection takes</a> before reconnecting.</p><p>If access needs attention, confirm that <code>spotify@podseo.com</code> is on the correct show&#39;s Spotify team with <strong>Analytics → Reader</strong>, and follow the status card. If PodSEO is already a team member, correct its access rather than sending a second invite. If the issue persists, <a href="https://podseo.com/contact/" target="_blank" rel="noreferrer">contact support</a> with the show and status shown.</p><h3 id="can-t-find-your-podcast-in-spotify-manage" tabindex="-1"><strong>Can&#39;t find your podcast in Spotify Manage?</strong> <a class="header-anchor" href="#can-t-find-your-podcast-in-spotify-manage" aria-label="Permalink to &quot;**Can&#39;t find your podcast in Spotify Manage?**&quot;">​</a></h3><p>If your podcast isn&#39;t in the list of teams, or Spotify says &quot;You&#39;re not on any teams yet&quot;, one of these is usually the reason.</p><p><strong>Your hosting platform put the show on Spotify for you, or you&#39;ve never used Spotify for Creators.</strong> Many hosts send your show to Spotify automatically, so it exists on Spotify but nobody has claimed it yet. Claiming is free:</p><ol><li>Sign in at <a href="https://creators.spotify.com" target="_blank" rel="noreferrer">Spotify for Creators</a> with any Spotify account. Already manage another show? Open your profile menu and choose <strong>Add a new show</strong>.</li><li>Choose <strong>Find an existing show</strong>, then <strong>Somewhere else</strong>, and enter your RSS feed or your Spotify show link.</li><li>Spotify emails an 8-digit code to the email address in your RSS feed. Enter it to finish the claim.</li><li>Your show now has a team in Spotify Manage: follow the connection steps above.</li></ol><p>Some hosts leave your email out of the RSS feed by default. If the code never arrives, add your email to the feed in your host&#39;s settings, then try again. Your host&#39;s own guide to claiming on Spotify usually shows where. In PodSEO, after you start the connection, open <strong>Problems connecting?</strong> on the Spotify tab: it shows your host&#39;s guide and checks whether your feed has an email Spotify can use.</p><p><strong>Someone else already claimed the show, or you have several logins.</strong> A show can be claimed only once. Try Spotify Manage with your other logins (personal, work, Google or Apple sign-in), or ask the current owner or admin to add you to the team. They can also send the PodSEO invite for you. Don&#39;t create a duplicate show.</p><p>Spotify&#39;s own guide: <a href="https://support.spotify.com/us/creators/article/claiming-your-podcast-on-spotify-for-creators/" target="_blank" rel="noreferrer">Claiming your podcast on Spotify for Creators</a>.</p><p>Wondering whether claiming is worth it when your host already sends the show to Spotify? See <a href="/academy/why-you-should-claim-your-podcast-on-apple-and-spotify.html">Why You Should Claim Your Podcast on Apple Podcasts and Spotify</a>.</p><h3 id="what-you-ll-see" tabindex="-1"><strong>What you&#39;ll see</strong> <a class="header-anchor" href="#what-you-ll-see" aria-label="Permalink to &quot;**What you&#39;ll see**&quot;">​</a></h3><ul><li><strong>Daily plays</strong> over time</li><li><strong>Discovery</strong>: impressions from <strong>Search</strong>, <strong>Home</strong>, <strong>Library</strong> and <strong>Other</strong>, and the funnel from impression to play, so you can see how often being seen turns into being listened to</li><li><strong>Engagement</strong>: new followers, hours listened (compared with the previous 30 days), and new versus returning listeners</li><li><strong>Audience</strong>: age, gender, countries, regions, cities, devices and listening apps</li><li><strong>Episodes</strong>: each episode&#39;s impressions, impressions from Search, and plays</li></ul><p>Spotify&#39;s <strong>Search</strong> source includes search results as well as charts and editorial exposure. Use it alongside your rankings, rather than treating every Search impression as a keyword search.</p><h3 id="how-fresh" tabindex="-1"><strong>How fresh</strong> <a class="header-anchor" href="#how-fresh" aria-label="Permalink to &quot;**How fresh**&quot;">​</a></h3><p>The plays overview is updated daily. Audience, engagement, discovery, benchmarks and episode reports can refresh on different schedules and retain their own reporting windows. Read the dates on each report; <a href="/features/spotify-analytics.html">Spotify analytics</a> explains the individual views.</p><h3 id="disconnecting" tabindex="-1"><strong>Disconnecting</strong> <a class="header-anchor" href="#disconnecting" aria-label="Permalink to &quot;**Disconnecting**&quot;">​</a></h3><p>Open <strong>Settings → Connections</strong>, expand Spotify for the correct show, and choose <strong>Disconnect…</strong>. Confirm after reviewing the notice. PodSEO stops reading your Spotify analytics and your Spotify numbers no longer show anywhere in PodSEO; PodSEO keeps them for when you reconnect. To end PodSEO&#39;s access completely, also remove <code>spotify@podseo.com</code> from your show&#39;s team in Spotify for Creators.</p><hr><h2 id="apple-podcasts-connect" tabindex="-1"><strong>Apple Podcasts Connect</strong> <a class="header-anchor" href="#apple-podcasts-connect" aria-label="Permalink to &quot;**Apple Podcasts Connect**&quot;">​</a></h2><p>Apple&#39;s data on plays, listeners, followers and how much of each episode people actually hear.</p><h3 id="how-to-connect-1" tabindex="-1"><strong>How to connect</strong> <a class="header-anchor" href="#how-to-connect-1" aria-label="Permalink to &quot;**How to connect**&quot;">​</a></h3><p>Your show must be listed on Apple Podcasts.</p><ol><li>Open <strong>Analytics</strong> and select the <strong>Apple Podcasts</strong> tab.</li><li>In <strong>Apple Podcasts Connect</strong>, go to <strong>Account</strong> &gt; <strong>People</strong> and invite <code>applepodcasts@podseo.com</code>.</li><li>Give the invite the <strong>Analyst</strong> role and select your show.</li><li>Send the invitation. PodSEO checks for new invitations every 10 minutes.</li></ol><p>Only the show&#39;s owner or one of its Admins in Apple Podcasts Connect can send the invite. If someone else manages the show on Apple (a producer, network or agency), forward them these steps.</p><h3 id="can-t-find-your-show-in-apple-podcasts-connect" tabindex="-1"><strong>Can&#39;t find your show in Apple Podcasts Connect?</strong> <a class="header-anchor" href="#can-t-find-your-show-in-apple-podcasts-connect" aria-label="Permalink to &quot;**Can&#39;t find your show in Apple Podcasts Connect?**&quot;">​</a></h3><p><strong>Your hosting platform put the show on Apple for you, or you never had an Apple Podcasts Connect account.</strong> Many hosts submit shows to Apple under their own Apple account, so the show isn&#39;t in yours and there&#39;s nobody to invite from. Apple lets you claim it, free:</p><ol><li>Copy your show&#39;s Apple Podcasts link (the Apple Podcasts tab in PodSEO shows it).</li><li>Sign in to <a href="https://podcastsconnect.apple.com" target="_blank" rel="noreferrer">Apple Podcasts Connect</a> with your own Apple Account (create a Podcasts Connect account if you need one). At the bottom of the page, under <strong>More Actions</strong>, click <strong>Claim Existing Show</strong>, paste the link and generate a token. Check the show&#39;s name and artwork before you do.</li><li>Paste the token in your hosting platform&#39;s Apple claim field. Every host names it differently (Acast has no dedicated field: paste it in your show&#39;s <strong>Settings</strong> → <strong>Copyright</strong> under Author Details, or <strong>Keywords</strong> under Discovery); in PodSEO, after you start the connection, open <strong>Problems connecting?</strong> on the Apple Podcasts tab to see where your host keeps it, a link to your host&#39;s own guide, and whether the token is in your feed yet.</li><li>Apple usually moves the show to your account within 24 hours; some hosts advise allowing a few days. Once it appears, follow the connection steps above.</li></ol><p>The token is valid for 7 days. Can&#39;t find the claim field in your host? Ask its support first. Apple&#39;s own guide: <a href="https://podcasters.apple.com/support/5497-claim-your-show" target="_blank" rel="noreferrer">Claim your show</a>.</p><p><strong>Can&#39;t claim it? Ask Apple for a show transfer.</strong> Apple doesn&#39;t allow claiming when it is disabled for the show, the show is in a channel or has a subscription, it has Apple-hosted audio or no RSS feed, it isn&#39;t available on Apple Podcasts, or your host doesn&#39;t support claiming yet. In those cases Apple moves the show for you: sign in with your own Apple Account and <a href="https://podcastsconnect.apple.com/contact-us?content_type=podcasts&amp;topic=show-transfer" target="_blank" rel="noreferrer">request a show transfer from Apple</a> (Apple&#39;s Contact Us form, with the show transfer topic already selected). To avoid delays, include:</p><ul><li>your show&#39;s Apple Podcasts link</li><li>its Apple Podcasts show ID (the number after <code>id</code> in the link)</li><li>its RSS feed URL</li><li>your email address</li><li>the Account ID of your own Apple Podcasts Connect account, the one the show should move to</li></ul><p>For a show delivered by RSS feed, Apple may ask you to edit some tags in the feed, which you can do in your host&#39;s settings. A show in an Apple Podcasts channel must be removed from the channel first. Apple&#39;s own guide: <a href="https://podcasters.apple.com/support/839-transfer-ownership-of-a-podcast" target="_blank" rel="noreferrer">Transfer ownership of a podcast</a>.</p><p><strong>On Castos?</strong> According to Castos support, shows that Castos has distributed for a long time from its own Apple account can&#39;t use the Castos claim token. If the token doesn&#39;t move your show, request the transfer from Apple as above.</p><p><strong>Someone else manages the show, or you have several Apple logins.</strong> Ask the show&#39;s owner or an Admin to send the invite, or try your other Apple accounts.</p><h3 id="why-claim-if-your-host-already-puts-the-show-on-apple" tabindex="-1"><strong>Why claim, if your host already puts the show on Apple?</strong> <a class="header-anchor" href="#why-claim-if-your-host-already-puts-the-show-on-apple" aria-label="Permalink to &quot;**Why claim, if your host already puts the show on Apple?**&quot;">​</a></h3><p>Nothing changes at your host or for listeners: the show stays hosted where it is and Apple keeps reading the same RSS feed. Apple charges nothing to claim. With the show in your own Apple Podcasts Connect account you can:</p><ul><li>See Apple&#39;s own listening data: followers, listeners, engaged listeners, plays, time listened, top countries and cities, per episode. Your host reports downloads, not this. Apple&#39;s guide: <a href="https://podcasters.apple.com/support/5392-listener-analytics" target="_blank" rel="noreferrer">Listener analytics</a>.</li><li>Upload artwork such as <strong>Full Page Show Art</strong>, a tall version of your cover shown on your Apple show page and in the player (<a href="https://podcasters.apple.com/support/5515-full-page-show-art-template" target="_blank" rel="noreferrer">Apple&#39;s template</a>).</li><li>Check your show&#39;s status on Apple and <strong>Refresh Feed</strong> when a new episode hasn&#39;t appeared yet (<a href="https://podcasters.apple.com/support/838-refresh-a-podcast" target="_blank" rel="noreferrer">Refresh a podcast</a>).</li><li>Add people with their own roles, such as PodSEO&#39;s view-only <strong>Analyst</strong> invite, which changes nothing in your show.</li></ul><p>The longer version, for Spotify too: <a href="/academy/why-you-should-claim-your-podcast-on-apple-and-spotify.html">Why You Should Claim Your Podcast on Apple Podcasts and Spotify</a>.</p><h3 id="proving-the-show-is-yours" tabindex="-1"><strong>Proving the show is yours</strong> <a class="header-anchor" href="#proving-the-show-is-yours" aria-label="Permalink to &quot;**Proving the show is yours**&quot;">​</a></h3><p>Before showing Apple data, PodSEO checks that the show belongs to you:</p><ul><li>If the <strong>owner email in your RSS feed</strong> matches a verified email on your PodSEO account (or on your organization&#39;s account), the check is automatic.</li><li>Otherwise, PodSEO sends a one-time link to the owner email in your RSS feed. The link is valid for 14 days. Whoever reads that mailbox clicks <strong>Yes, this is us</strong> to confirm, or <strong>No, I don&#39;t know PodSEO</strong> to refuse.</li><li>If your RSS feed has no owner email, PodSEO checks whether your show&#39;s website (from the feed) and a verified email on your PodSEO account share the same domain. If they don&#39;t, the PodSEO team confirms the show with you.</li></ul><p>Once one show is proven, other shows from the same Apple Podcasts Connect team are approved too.</p><p><a href="/images/analytics_apple.webp" title="Open screenshot at full size"><img src="'+o+'" alt="Apple Podcasts listening overview"></a></p><h3 id="what-you-ll-see-1" tabindex="-1"><strong>What you&#39;ll see</strong> <a class="header-anchor" href="#what-you-ll-see-1" aria-label="Permalink to &quot;**What you&#39;ll see**&quot;">​</a></h3><ul><li><strong>Plays</strong> and <strong>Hours listened</strong> for the selected period, with a daily plays chart; <strong>Listeners</strong> retains Apple&#39;s own last-60-days window</li><li><strong>Followers</strong>: total, gained, lost and net</li><li><strong>Time listened</strong> by followers compared with everyone else</li><li><strong>Monthly history</strong> of Plays, Listeners, Engaged listeners and Hours</li><li><strong>Episodes table</strong> with Plays, Listeners, Engaged, Avg. listened, First 7 days and First 30 days for each episode, plus a <strong>retention curve</strong> per episode showing where listeners drop off</li><li><strong>Audience</strong>: countries, top cities and the available follower comparisons, each with its own reporting window</li></ul><p>Use the <strong>30</strong>, <strong>90</strong> and <strong>365 days</strong> controls for the reports that follow the selected period. Listener totals, episode measurements and audience snapshots retain their own labelled windows.</p><h3 id="how-fresh-1" tabindex="-1"><strong>How fresh</strong> <a class="header-anchor" href="#how-fresh-1" aria-label="Permalink to &quot;**How fresh**&quot;">​</a></h3><p>Apple data is read daily. Apple provides a limited daily history; PodSEO retains the days already read, so longer views build up over time. Each report keeps its own dates. See <a href="/features/apple-podcasts-analytics.html">Apple Podcasts analytics</a> for coverage, episode reports and unavailable values.</p><h3 id="disconnecting-1" tabindex="-1"><strong>Disconnecting</strong> <a class="header-anchor" href="#disconnecting-1" aria-label="Permalink to &quot;**Disconnecting**&quot;">​</a></h3><p>Open <strong>Settings → Connections</strong>, expand Apple Podcasts for the correct show, and choose <strong>Disconnect…</strong>. PodSEO stops reading your Apple analytics and your Apple numbers no longer show anywhere in PodSEO; PodSEO keeps them for when you reconnect. To end PodSEO&#39;s access completely, also remove <code>applepodcasts@podseo.com</code> from <strong>Account</strong> &gt; <strong>People</strong> in Apple Podcasts Connect.</p><hr><h2 id="youtube" tabindex="-1"><strong>YouTube</strong> <a class="header-anchor" href="#youtube" aria-label="Permalink to &quot;**YouTube**&quot;">​</a></h2><p>How people find and watch your podcast on YouTube, including the real search terms that bring viewers in.</p><h3 id="how-to-connect-2" tabindex="-1"><strong>How to connect</strong> <a class="header-anchor" href="#how-to-connect-2" aria-label="Permalink to &quot;**How to connect**&quot;">​</a></h3><ol><li>Open <strong>Analytics</strong> and select the <strong>YouTube</strong> tab (or click it to open the YouTube Insights page).</li><li>Click <strong>Connect YouTube</strong> and sign in with the Google account (or Brand Account) that owns your podcast&#39;s channel.</li><li>You return to <strong>Analytics → YouTube</strong>. Check the channel&#39;s name. Your first connection activates Insights automatically and starts importing the last six months. If the page shows <strong>Activate Insights</strong> for an existing connection, click it; no new sign-in is needed.</li></ol><h3 id="what-you-ll-see-2" tabindex="-1"><strong>What you&#39;ll see</strong> <a class="header-anchor" href="#what-you-ll-see-2" aria-label="Permalink to &quot;**What you&#39;ll see**&quot;">​</a></h3><ul><li><strong>Views</strong>, <strong>Watch hours</strong>, <strong>Subscribers</strong> (net) and the <strong>% of views from YouTube search</strong>, with a daily views chart</li><li><strong>Traffic sources</strong> and external referrers</li><li><strong>Search terms</strong> YouTube reports, compared with the keywords you track in PodSEO</li><li><strong>Episode-to-video matching</strong>, with keyword-based title suggestions for your videos</li><li><strong>Audience</strong>: countries, age and gender, cities, US states, operating systems and playback locations</li><li>Your <strong>podcast playlists</strong></li></ul><p>Use the <strong>7</strong>, <strong>28</strong> and <strong>90 days</strong> tabs to change the period.</p><h3 id="how-fresh-2" tabindex="-1"><strong>How fresh</strong> <a class="header-anchor" href="#how-fresh-2" aria-label="Permalink to &quot;**How fresh**&quot;">​</a></h3><p>Core figures are updated daily; the breakdowns (such as audience and traffic details) weekly.</p><h3 id="free-plan-limit" tabindex="-1"><strong>Free plan limit</strong> <a class="header-anchor" href="#free-plan-limit" aria-label="Permalink to &quot;**Free plan limit**&quot;">​</a></h3><p>On the Free plan you see channel performance, one reported search term and your latest episode. Paid plans show everything.</p><h3 id="disconnecting-2" tabindex="-1"><strong>Disconnecting</strong> <a class="header-anchor" href="#disconnecting-2" aria-label="Permalink to &quot;**Disconnecting**&quot;">​</a></h3><p>Disconnecting YouTube removes its analytics data unless that channel is still connected to another of your podcasts. A broken authorization has a 30-day retention window before deletion. Read the confirmation in Settings → Connections before proceeding. For the full walkthrough of YouTube, see <a href="/features/youtube-insights.html">YouTube Insights</a>.</p><hr><h2 id="hosting-spreaker-buzzsprout-simplecast-captivate-transistor-and-podigee" tabindex="-1"><strong>Hosting (Spreaker, Buzzsprout, Simplecast, Captivate, Transistor and Podigee)</strong> <a class="header-anchor" href="#hosting-spreaker-buzzsprout-simplecast-captivate-transistor-and-podigee" aria-label="Permalink to &quot;**Hosting (Spreaker, Buzzsprout, Simplecast, Captivate, Transistor and Podigee)**&quot;">​</a></h2><p>Downloads straight from your podcast host. Spreaker, Buzzsprout, Simplecast, Captivate, Transistor and Podigee are supported.</p><h3 id="how-to-connect-3" tabindex="-1"><strong>How to connect</strong> <a class="header-anchor" href="#how-to-connect-3" aria-label="Permalink to &quot;**How to connect**&quot;">​</a></h3><p>The host tab (labelled <strong>Spreaker</strong>, <strong>Buzzsprout</strong>, <strong>Simplecast</strong>, <strong>Captivate</strong>, <strong>Transistor</strong> or <strong>Podigee</strong>) appears when your podcast&#39;s feed is hosted on one of them.</p><p><strong>Spreaker</strong></p><ol><li>Open <strong>Analytics</strong> and select your <strong>Spreaker</strong> tab.</li><li>Click <strong>Sign in to Spreaker</strong>.</li><li>Approve the request with <strong>Authorize</strong>. You&#39;re sent back to PodSEO and the first sync begins.</li></ol><p><strong>Buzzsprout</strong></p><ol><li>In Buzzsprout, open your profile and its <strong>API</strong> section, then copy the API token of the account that hosts your podcast.</li><li>In PodSEO, open <strong>Analytics</strong> and select your <strong>Buzzsprout</strong> tab.</li><li>Paste the token and click <strong>Connect Buzzsprout</strong>. PodSEO matches your podcast through its RSS feed and the first sync begins.</li></ol><p>A Buzzsprout token can also edit your Buzzsprout account. PodSEO stores it encrypted and only uses it to read reports, never to change anything.</p><p><strong>Simplecast</strong></p><ol><li>In Simplecast, open the account menu (top right) → <strong>Account Settings</strong> → <strong>Private Apps</strong>, then copy the <strong>Read-Only API Token</strong>.</li><li>In PodSEO, open <strong>Analytics</strong> and select your <strong>Simplecast</strong> tab.</li><li>Paste the token and click <strong>Connect Simplecast</strong>. PodSEO matches your podcast through its RSS feed and the first sync begins.</li></ol><p>The Simplecast token is read-only: it can&#39;t change anything in your Simplecast account. PodSEO stores it encrypted.</p><p><strong>Captivate</strong></p><ol><li>In Captivate, click your name (top right) → <strong>My Account</strong> → <strong>API key</strong>, then click <strong>Reveal API Key</strong>.</li><li>Copy both the <strong>User ID</strong> and the <strong>API Key</strong>.</li><li>In PodSEO, open <strong>Analytics</strong> and select your <strong>Captivate</strong> tab.</li><li>Paste both values and click <strong>Connect Captivate</strong>. PodSEO matches your podcast through its RSS feed (or, for a feed on your own domain, its newest episodes) and the first sync begins.</li></ol><p>A Captivate API key can also edit your Captivate shows. PodSEO stores it encrypted and only uses it to read reports, never to change anything.</p><p><strong>Transistor</strong></p><ol><li>In Transistor, click your avatar (top right) → <strong>Manage Your Account</strong>.</li><li>In the <strong>API Access</strong> section, copy <strong>Your API Key</strong>.</li><li>In PodSEO, open <strong>Analytics</strong> and select your <strong>Transistor</strong> tab.</li><li>Paste the key and click <strong>Connect Transistor</strong>. PodSEO matches your podcast through its RSS feed (or, for a feed behind a custom domain or a tracking prefix, its newest episodes) and the first sync begins.</li></ol><p>A Transistor API key can also edit your Transistor shows. PodSEO stores it encrypted and only uses it to read reports, never to change anything.</p><p><strong>Podigee</strong></p><ol><li>In Podigee, open the account menu (your name, bottom left) → <strong>Data &amp; integrations</strong>.</li><li>Under <strong>API keys</strong>, click <strong>Create MCP token</strong>. Name it PodSEO, choose <strong>Read only</strong> and <strong>Until I remove it</strong>, then click <strong>Create token</strong>.</li><li>Copy the token: Podigee shows it only once. It starts with <code>pdg_pat_</code>.</li><li>In PodSEO, open <strong>Analytics</strong>, select your <strong>Podigee</strong> tab, paste the token and click <strong>Connect Podigee</strong>. PodSEO matches your podcast through its RSS feed (or, for a feed on your own domain, its newest episodes) and the first sync begins.</li></ol><p>This works on every Podigee plan, Launch included. Your show needs at least one published episode: Podigee shares no statistics before that. A Read only token cannot change anything in your Podigee account.</p><p><strong>Megaphone</strong></p><p>Megaphone connects by invitation instead of a token: open <strong>Analytics</strong>, select your <strong>Megaphone</strong> tab and click <strong>Connect Megaphone</strong>. PodSEO gives you a code; in Megaphone, invite <code>megaphone@podseo.com</code> as a read-only <strong>Network Partner</strong> of the network that holds your show, with the code as the Last name. Follow the full walkthrough, with screenshots, in <a href="/features/megaphone-connection.html">Connect Megaphone</a>.</p><p><a href="/images/analytics_hosting.webp" title="Open screenshot at full size"><img src="'+t+'" alt="Hosting download overview"></a></p><h3 id="what-you-ll-see-3" tabindex="-1"><strong>What you&#39;ll see</strong> <a class="header-anchor" href="#what-you-ll-see-3" aria-label="Permalink to &quot;**What you&#39;ll see**&quot;">​</a></h3><ul><li><strong>Downloads</strong>, <strong>Daily average</strong> and <strong>Best day</strong> for the period, with a daily chart</li><li><strong>Episodes</strong> with Total downloads, First 7 days and First 30 days, so you can compare launches fairly</li><li><strong>Unique listeners per week</strong>, as Spreaker or Simplecast report them (Simplecast only when your Simplecast plan includes them; Buzzsprout doesn&#39;t report unique listeners)</li><li><strong>Who listens</strong>: countries, apps, devices and operating systems, when your Spreaker plan includes them. With Buzzsprout: countries, devices and the apps listeners download each episode with, day by day. With Simplecast: countries, apps, devices and operating systems. With Captivate: countries, apps, devices and operating systems, for the show and for each episode (Captivate&#39;s weekly unique listeners aren&#39;t shown). Transistor reports downloads only: you get the downloads overview and the episode comparison, without listening apps, countries or unique listeners. Podigee reports downloads and the apps listeners use, for the show and for each episode, without countries, devices or unique listeners</li></ul><h3 id="how-fresh-3" tabindex="-1"><strong>How fresh</strong> <a class="header-anchor" href="#how-fresh-3" aria-label="Permalink to &quot;**How fresh**&quot;">​</a></h3><p>Downloads are synced daily. Spreaker audience details refresh weekly and the first sync backfills the last 365 days. Buzzsprout audience details refresh daily and the first sync reads all the history Buzzsprout still has. Simplecast audience details refresh weekly and the first sync reads your show&#39;s whole history. Captivate audience details refresh weekly and the first sync reads everything since your show joined Captivate. Transistor&#39;s first sync reads everything since your show was created on Transistor. Podigee&#39;s history goes back as far as your Podigee plan keeps statistics (7 days on Launch, 90 days on Starter, 6 months on Grow, 12 months on Scale, everything on Creator and above); PodSEO keeps every day it has read from then on, so connect early.</p><h3 id="disconnecting-3" tabindex="-1"><strong>Disconnecting</strong> <a class="header-anchor" href="#disconnecting-3" aria-label="Permalink to &quot;**Disconnecting**&quot;">​</a></h3><p>Open <strong>Settings → Connections</strong>, expand your host for the correct show, and choose <strong>Disconnect…</strong>. PodSEO stops reading your downloads and deletes the access it stored. Your host numbers no longer show anywhere in PodSEO; PodSEO keeps them for when you reconnect.</p><ul><li><strong>Spreaker</strong>: PodSEO also asks Spreaker to revoke its access. You can check the connected apps in your Spreaker settings.</li><li><strong>Buzzsprout</strong>: Buzzsprout has no way for PodSEO to revoke a token. To invalidate it, delete or regenerate it in your Buzzsprout profile.</li><li><strong>Simplecast</strong>: to invalidate the token, regenerate it in Simplecast under <strong>Account Settings</strong> → <strong>Private Apps</strong>.</li><li><strong>Captivate</strong>: to invalidate the key, click <strong>Regenerate API Key</strong> in Captivate under <strong>My Account</strong> → <strong>API key</strong>. Other apps that use the same key will need reconnecting.</li><li><strong>Transistor</strong>: to invalidate the key, click <strong>Expire API Key</strong> in Transistor under <strong>Manage Your Account</strong> → <strong>API Access</strong>. Other apps that use the same key will need reconnecting.</li><li><strong>Podigee</strong>: to invalidate the token, click <strong>Remove</strong> next to it in Podigee under <strong>Data &amp; integrations</strong> → <strong>API keys</strong>.</li><li><strong>Megaphone</strong>: remove <code>megaphone@podseo.com</code> from your Megaphone users to end PodSEO&#39;s access to your organization.</li></ul><hr><h2 id="op3-tracker-tab" tabindex="-1"><strong>OP3 (Tracker tab)</strong> <a class="header-anchor" href="#op3-tracker-tab" aria-label="Permalink to &quot;**OP3 (Tracker tab)**&quot;">​</a></h2><p><a href="https://op3.dev" target="_blank" rel="noreferrer">OP3</a> is a free, open podcast download tracker that many podcasters add to their feed as a prefix.</p><h3 id="how-to-connect-4" tabindex="-1"><strong>How to connect</strong> <a class="header-anchor" href="#how-to-connect-4" aria-label="Permalink to &quot;**How to connect**&quot;">​</a></h3><p>There&#39;s nothing to connect. If your RSS feed already carries the OP3 prefix, PodSEO finds it on its own (it checks your feed weekly) and the <strong>Tracker</strong> tab shows your numbers.</p><h3 id="what-you-ll-see-4" tabindex="-1"><strong>What you&#39;ll see</strong> <a class="header-anchor" href="#what-you-ll-see-4" aria-label="Permalink to &quot;**What you&#39;ll see**&quot;">​</a></h3><ul><li><strong>Downloads per episode</strong> at 1, 7 and 30 days after release</li><li>Your <strong>Latest</strong>, <strong>Typical</strong> and <strong>Best</strong> episode, so you can tell at a glance whether a new episode is doing better or worse than usual</li><li>A separate total of <strong>downloads from listening apps</strong>, which excludes web browsers. The episode counts include browser downloads; see <a href="/features/op3-analytics.html">OP3 data</a>.</li></ul><h3 id="how-fresh-4" tabindex="-1"><strong>How fresh</strong> <a class="header-anchor" href="#how-fresh-4" aria-label="Permalink to &quot;**How fresh**&quot;">​</a></h3><p>OP3 data is public, so anyone can look at it, and it covers about 60 days of history.</p><h3 id="disconnecting-4" tabindex="-1"><strong>Disconnecting</strong> <a class="header-anchor" href="#disconnecting-4" aria-label="Permalink to &quot;**Disconnecting**&quot;">​</a></h3><p>Because PodSEO reads public OP3 data, there&#39;s no connection to remove. To stop OP3 tracking altogether, remove the OP3 prefix in your host&#39;s settings.</p><hr><h2 id="hopr-fm-podseo-s-download-prefix" tabindex="-1"><strong>hopr.fm (PodSEO&#39;s Download Prefix)</strong> <a class="header-anchor" href="#hopr-fm-podseo-s-download-prefix" aria-label="Permalink to &quot;**hopr.fm (PodSEO&#39;s Download Prefix)**&quot;">​</a></h2><p>hopr.fm is PodSEO&#39;s own download prefix. Like other analytics prefixes, it sits in front of your audio files and counts each download on its way to the listener. It&#39;s useful when your host doesn&#39;t give you good download numbers, or when you want a second, independent count.</p><h3 id="how-to-connect-5" tabindex="-1"><strong>How to connect</strong> <a class="header-anchor" href="#how-to-connect-5" aria-label="Permalink to &quot;**How to connect**&quot;">​</a></h3><ol><li>Open <strong>Analytics</strong> and select the <strong>hopr.fm</strong> tab.</li><li>Click <strong>Get my prefix</strong>. PodSEO creates your personal prefix in the form <code>https://hopr.fm/k/&lt;your key&gt;/</code>.</li><li>In your podcast host, find the <strong>prefix</strong> or <strong>analytics prefix</strong> field (hosts name it differently) and paste the prefix there. It works alongside any other prefixes you already use.</li><li>Save. Back in PodSEO you can ask it to re-check your feed, to confirm the prefix is in place.</li></ol><p><a href="/images/analytics_hopr.webp" title="Open screenshot at full size"><img src="'+s+'" alt="hopr.fm downloads and reporting views"></a></p><h3 id="what-you-ll-see-5" tabindex="-1"><strong>What you&#39;ll see</strong> <a class="header-anchor" href="#what-you-ll-see-5" aria-label="Permalink to &quot;**What you&#39;ll see**&quot;">​</a></h3><ul><li><strong>Downloads</strong> for the period, with the change compared with the previous period</li><li><strong>Apps</strong>, <strong>countries</strong> and <strong>episodes</strong></li><li><strong>Not counted</strong>: the requests that were left out and why: cloud apps, servers, bots, preloads, and requests with no user agent. A toggle lets you include cloud apps in the count if you want to.</li></ul><p>Only your account can see your hopr.fm reports.</p><h3 id="how-downloads-are-counted" tabindex="-1"><strong>How downloads are counted</strong> <a class="header-anchor" href="#how-downloads-are-counted" aria-label="Permalink to &quot;**How downloads are counted**&quot;">​</a></h3><p>hopr.fm counts <strong>one download per day, per episode, per listener</strong>. To tell listeners apart without storing who they are, each listener is turned into a one-way code that changes every day. The method follows the IAB v2.3 measurement guidelines as far as a redirect prefix allows, but hopr.fm is <strong>not IAB certified</strong>.</p><h3 id="listener-privacy" tabindex="-1"><strong>Listener privacy</strong> <a class="header-anchor" href="#listener-privacy" aria-label="Permalink to &quot;**Listener privacy**&quot;">​</a></h3><p>hopr.fm only redirects the request to your audio file. It sets no cookies, deletes raw logs and per-listener records after 35 days, never sells data or builds ad profiles, and podcasters only ever see totals. The full listener privacy policy is at <a href="https://podseo.com/hoprfm/privacy/" target="_blank" rel="noreferrer">podseo.com/hoprfm/privacy</a>.</p><h3 id="how-fresh-5" tabindex="-1"><strong>How fresh</strong> <a class="header-anchor" href="#how-fresh-5" aria-label="Permalink to &quot;**How fresh**&quot;">​</a></h3><p>Downloads are processed throughout the day.</p><h3 id="disconnecting-5" tabindex="-1"><strong>Disconnecting</strong> <a class="header-anchor" href="#disconnecting-5" aria-label="Permalink to &quot;**Disconnecting**&quot;">​</a></h3><p>Remove the hopr.fm prefix from your host&#39;s settings. Downloads that no longer pass through the prefix aren&#39;t counted.</p><hr><h2 id="faq" tabindex="-1"><strong>FAQ</strong> <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;**FAQ**&quot;">​</a></h2><h3 id="do-i-have-to-share-my-passwords-with-podseo" tabindex="-1"><strong>Do I have to share my passwords with PodSEO?</strong> <a class="header-anchor" href="#do-i-have-to-share-my-passwords-with-podseo" aria-label="Permalink to &quot;**Do I have to share my passwords with PodSEO?**&quot;">​</a></h3><p>No. Spotify and Apple Podcasts are connected by inviting a PodSEO address to your show&#39;s team with read-only analytics access. YouTube and Spreaker use their own sign-in screens, where you approve access directly with Google or Spreaker. Buzzsprout, Simplecast, Captivate, Transistor and Podigee use an API token or key you copy from your host account (Simplecast&#39;s and Podigee&#39;s are read-only), not your password. PodSEO never sees your passwords, and you can disconnect at any time.</p><h3 id="which-podcast-hosts-can-i-connect" tabindex="-1"><strong>Which podcast hosts can I connect?</strong> <a class="header-anchor" href="#which-podcast-hosts-can-i-connect" aria-label="Permalink to &quot;**Which podcast hosts can I connect?**&quot;">​</a></h3><p>Spreaker, Buzzsprout, Simplecast, Captivate, Transistor and Podigee. If your host isn&#39;t supported yet, you can still get download numbers from OP3 (if your feed uses it) or by adding the free hopr.fm prefix, and connect Spotify, Apple Podcasts and YouTube regardless of where you host.</p><h3 id="what-s-the-difference-between-hopr-fm-and-op3" tabindex="-1"><strong>What&#39;s the difference between hopr.fm and OP3?</strong> <a class="header-anchor" href="#what-s-the-difference-between-hopr-fm-and-op3" aria-label="Permalink to &quot;**What&#39;s the difference between hopr.fm and OP3?**&quot;">​</a></h3><p>Both are download prefixes that count downloads on the way to the listener. OP3 is an independent, open service: its data is public to anyone and PodSEO shows about 60 days of it, with downloads per episode at 1, 7 and 30 days. hopr.fm is PodSEO&#39;s own prefix: its reports are private to your account, show apps, countries, episodes and a breakdown of what wasn&#39;t counted, and you choose whether to count cloud apps. You can use both at the same time.</p><h3 id="is-this-really-free" tabindex="-1"><strong>Is this really free?</strong> <a class="header-anchor" href="#is-this-really-free" aria-label="Permalink to &quot;**Is this really free?**&quot;">​</a></h3><p>Yes. Every connection is available on every plan, including Free. The one difference is YouTube: on the Free plan you see channel performance, one reported search term and your latest episode, while paid plans show every search term and all your recent episodes.</p><h3 id="why-don-t-my-numbers-match-exactly-between-sources" tabindex="-1"><strong>Why don&#39;t my numbers match exactly between sources?</strong> <a class="header-anchor" href="#why-don-t-my-numbers-match-exactly-between-sources" aria-label="Permalink to &quot;**Why don&#39;t my numbers match exactly between sources?**&quot;">​</a></h3><p>Each platform measures something different: Spotify and Apple count plays and listeners in their own apps, YouTube counts views, and hosts and prefixes count downloads across all apps. That&#39;s why PodSEO shows each source on its own tab instead of mixing them into one number.</p><h3 id="i-m-a-team-member-and-can-t-connect-why" tabindex="-1"><strong>I&#39;m a team member and can&#39;t connect. Why?</strong> <a class="header-anchor" href="#i-m-a-team-member-and-can-t-connect-why" aria-label="Permalink to &quot;**I&#39;m a team member and can&#39;t connect. Why?**&quot;">​</a></h3><p>In an organization, only Admins and Owners can connect or disconnect analytics sources. Ask one of them to set up the connection; once it&#39;s done, everyone on the team can see the numbers.</p><hr><h3 id="pro-tips" tabindex="-1"><strong>Pro Tips</strong> <a class="header-anchor" href="#pro-tips" aria-label="Permalink to &quot;**Pro Tips**&quot;">​</a></h3><ul><li>Start with the platforms where most of your audience listens, then add your host or a download prefix for a count across all apps.</li><li>Compare Spotify&#39;s <strong>impressions from Search</strong> with your <a href="/features/keyword-tracker.html">Keyword Tracker</a> rankings: rising rankings should show up as more search impressions.</li><li>Use the <strong>First 7 days</strong> and <strong>First 30 days</strong> columns (Apple and your host) to compare episodes fairly, regardless of how long ago they were published.</li><li>Check the Apple <strong>retention curve</strong> for episodes with a big drop early on: it shows where listeners leave, so you can compare it with how the episode opens.</li><li>If your host isn&#39;t supported yet, add the hopr.fm prefix: it takes a minute and gives you download numbers from that day on.</li></ul>',168)])])}const S=n(l,[["render",d]]);export{k as __pageData,S as default};
